  it('feeds a rejected tool call back to the provider as a tool_result and resolves when the next round corrects it', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'find_city',
        description: 'Look up a city',
        inputSchema: {
          type: 'object',
          properties: {city: {type: 'string'}},
          required: ['city'],
        },
      },
      async input => `found ${String(input.city)}`
    );

    const seenToolResults: string[] = [];
    const rounds: MessageChunk[][] = [
      [{type: 'tool_use', toolCall: {id: 'c1', name: 'find_city', input: {}}}, STOP_FOR_TOOL],
      [{type: 'tool_use', toolCall: {id: 'c2', name: 'find_city', input: {city: 'Berlin'}}}, STOP_FOR_TOOL],
      [{type: 'text', text: 'Berlin found'}, STOP_DONE],
    ];
    let step = 0;
    const provider: AIProvider = {
      async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
        const tail = params.messages[params.messages.length - 1];
        if (tail && tail.role === 'user' && Array.isArray(tail.content)) {
          seenToolResults.push((tail as ToolResultMessage).content.map(item => item.content).join('|'));
        }
        for (const chunk of rounds[step++] ?? []) yield chunk;
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };

    const orchestrator = createChatOrchestrator(provider, promptBuilder, registry);
    const answer = await orchestrator.processMessage(createSession('find Berlin'));

    expect({
      answer,
      firstResultHasCity: seenToolResults[0]?.includes('city') ?? false,
      secondResult: seenToolResults[1],
    }).toEqual({
      answer: 'Berlin found',
      firstResultHasCity: true,
      secondResult: 'found Berlin',
    });
  });
});

